class Solution {
    public int countVowels(String s) {
        int n = 0;
        for (char c : s.toLowerCase().toCharArray()) {
            if ("aeiou".indexOf(c) >= 0) n++;
        }
        return n;
    }
}

reference.python:
class Solution:
    def countVowels(self, s: str) -> int:
        return sum(c in 'aeiouAEIOU' for c in s)

